/* Display the user's original photograph as an undistorted backdrop, not a 360 panorama. */
AFRAME.registerComponent('image-backdrop',{
 schema:{src:{type:'string'}},
 init(){const T=AFRAME.THREE;this.direction=new T.Vector3();this.position=new T.Vector3();this.quaternion=new T.Quaternion();this.aspect=1;this.distance=35;this.previous=this.el.object3D.background;this.el.object3D.background=new T.Color('#cbd0c8');this.material=new T.MeshBasicMaterial({color:'#ffffff',fog:false,depthTest:false,depthWrite:false,toneMapped:false});this.mesh=new T.Mesh(new T.PlaneGeometry(1,1),this.material);this.mesh.renderOrder=-10000;this.mesh.frustumCulled=false;this.mesh.onBeforeRender=(renderer,scene,camera)=>this.fitCamera(camera);this.mesh.visible=false;this.el.object3D.add(this.mesh);this.texture=new T.TextureLoader().load(this.data.src,texture=>{if(this.removed)return;texture.colorSpace=T.SRGBColorSpace;texture.minFilter=T.LinearFilter;texture.magFilter=T.LinearFilter;texture.generateMipmaps=false;this.aspect=(texture.image.naturalWidth||texture.image.width)/(texture.image.naturalHeight||texture.image.height);this.material.map=texture;this.material.needsUpdate=true;this.ready=true},undefined,()=>{const status=document.getElementById('status');if(status)status.textContent='The selected background could not load. Reload to retry.'})},
 fitCamera(camera){if(!this.ready||!camera)return;this.position.setFromMatrixPosition(camera.matrixWorld);this.quaternion.setFromRotationMatrix(camera.matrixWorld);this.direction.set(0,0,-1).applyQuaternion(this.quaternion).normalize();this.mesh.position.copy(this.position).addScaledVector(this.direction,this.distance);this.mesh.quaternion.copy(this.quaternion);const projection=camera.projectionMatrix?.elements;const halfHeight=projection?.[5]?1/Math.abs(projection[5]):Math.tan((camera.fov||80)*Math.PI/360),halfWidth=projection?.[0]?1/Math.abs(projection[0]):halfHeight*(camera.aspect||1);const viewportHeight=2*this.distance*halfHeight*(1+Math.abs(projection?.[9]||0))*1.08,viewportWidth=2*this.distance*halfWidth*(1+Math.abs(projection?.[8]||0))*1.08;let height=viewportHeight,width=height*this.aspect;if(width<viewportWidth){width=viewportWidth;height=width/this.aspect}this.mesh.scale.set(width,height,1);this.mesh.updateMatrixWorld(true)},
 tick(){if(!this.ready||!this.el.camera)return;this.mesh.visible=!this.el.is('ar-mode');if(!this.mesh.visible)return;this.fitCamera(this.el.camera);document.body?.classList.add('scene-ready')},
 remove(){this.removed=true;document.body?.classList.remove('scene-ready');this.mesh?.parent?.remove(this.mesh);this.mesh?.geometry.dispose();this.material?.dispose();this.texture?.dispose();this.el.object3D.background=this.previous}
});
